namespace ghidra.framework.plugintool.dialog;







using docking.util.image;
using docking.widgets.list;
using generic.theme.GThemeDefaults.Colors;

class ToolIconUrlRenderer : GListCellRenderer<ToolIconURL> {
	private Border emptyBorder = BorderFactory.createEmptyBorder(5, 5, 5, 5);
	private Border selectedBorder = BorderFactory.createLineBorder(Palette.BLUE, 2);
	private Border emptySelectedBorder = BorderFactory.createEmptyBorder(3, 3, 3, 3);
	private Border selectedCompoundBorder =
		BorderFactory.createCompoundBorder(emptySelectedBorder, selectedBorder);

	ToolIconUrlRenderer() {
		setBorder(emptyBorder);
		setShouldAlternateRowBackgroundColors(false);
	}

	/* @Override */
	protected string getItemText(ToolIconURL value) {
		return "";
	}

	/* @Override */
	public Component getListCellRendererComponent(JList<ToolIconURL> list,
			ToolIconURL toolIconUrl, int index, bool isSelected, bool cellHasFocus) {

		// lie to our parent about the selected status to disable the background selection color
		base.getListCellRendererComponent(list, toolIconUrl, index, false, cellHasFocus);
		setIcon(toolIconUrl.getIcon());
		setBorder(isSelected ? selectedCompoundBorder : emptyBorder);
		return this;
	}

}
